import{_ as i,l as o,o as e,c as n,v as t,p as s,x as l,d as p,i as d,S as m}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"动态采样","description":"","frontmatter":{"title":"动态采样","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dynamic-sampling-rl.md","filePath":"llm/dynamic-sampling-rl.md","lastUpdated":1789023840000}'),h={name:"llm/dynamic-sampling-rl.md"};function c(E,a,_,A,B,f){const r=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="动态采样" tabindex="-1">动态采样 <a class="header-anchor" href="#动态采样" aria-label="Permalink to &quot;动态采样&quot;">​</a></h1><div class="epigraph"><p>全对或全错的组没有相对梯度；滤掉它们、过采样直到 batch 有信号，是目标定义的一部分，不是可选技巧。</p><footer>—— Yu 等 DAPO 的 Dynamic Sampling；约束写在目标的 s.t. 里</footer></div><p><a href="/llm/overlong-filtering">上一课</a>处理截断标签。即使长度健康，<a href="/llm/grpo">GRPO</a> 仍会在准确率为 0 或 1 的题上得到零优势。缺口是：<strong>有效 batch 随训练变瘦，更新浪费在无信号组上。</strong> DAPO 的动态采样要求 \\(0\\lt |\\{o_i:\\text{答对}\\}|\\lt G\\)，buffer 未满就继续采。本课写这一约束。消融上它把分数从 42 推到 50，是四件套里最大的一块。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>组内标准化在 \\(\\mathrm{std}=0\\) 时要么 NaN，要么 \\(\\hat A=0\\)。训练后期易题全对、难题全错，两种组变多。继续更新等于空转，还可能被数值噪声推动。静态题库 + 固定 \\(G\\) 无法保证每步都有相对信号。动态采样改变的是<strong>进入梯度的题分布</strong>：变难、变「当前策略仍会分叉」的题。</p><p>这不是普通的难度课程（后课）。课程按预设难度排序；动态采样按<strong>当前通过率</strong>过滤，同一题会在策略变好后从有信号变成全对再被滤掉。</p><h3 id="墙钟直觉经常是反的" tabindex="-1">墙钟直觉经常是反的 <a class="header-anchor" href="#墙钟直觉经常是反的" aria-label="Permalink to &quot;墙钟直觉经常是反的&quot;">​</a></h3><p>多滤几条似乎更贵。DAPO 原文图显示总时间可以下降：少做无效更新，收敛更快。但题库整体过难、通过率长期接近 0 时，会一直采不到满 batch，墙钟爆炸。必须有超时与回退（降低难度、升温、暂时允许部分零梯度）。</p><p><span class="marginnote">\\(G=1\\) 时相对优势未定义，动态采样救不了，应改 PPO 或 REINFORCE++。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对每个 prompt 采 \\(G\\) 条、算 \\(R\\)。若全 0 或全 1，丢弃该 prompt，从队列再取。凑满训练 batch 再更新。过采样上限要设：同一 prompt 不要无限重采。统计：丢弃率、为满 batch 额外生成的倍数、各难度的存活率。奖励必须是可比较的对错；高噪声 RM 上「全对」没有意义，动态采样会滤掉的是「分数碰巧相同」，可能删掉有用的序信息。</p>',11)),(e(),s(m,null,{default:l(()=>[d(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E9%A2%98%20x%22%5D%20--%3E%20G%5B%22%E9%87%87%20G%20%E6%9D%A1%22%5D%0A%20%20G%20--%3E%20R%5B%22%E7%BB%84%E5%86%85%20R%22%5D%0A%20%20R%20--%3E%20CHK%7B%220%20%EF%BC%9C%20%E7%AD%94%E5%AF%B9%E6%95%B0%20%EF%BC%9C%20G%22%7D%0A%20%20CHK%20--%3E%7C%E5%90%A6%7C%20DROP%5B%22%E4%B8%A2%E5%BC%83%EF%BC%8C%E5%86%8D%E9%87%87%E6%A0%B7%22%5D%0A%20%20CHK%20--%3E%7C%E6%98%AF%7C%20BUF%5B%22%E8%BF%9B%E5%85%A5%E8%AE%AD%E7%BB%83%20batch%22%5D%0A%20%20BUF%20--%3E%20UPD%5B%22GRPO%20%2F%20DAPO%20%E6%9B%B4%E6%96%B0%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与熵正则正交：有熵仍可能全对（换词同对）。动态采样看的是奖励方差，不是 token 熵。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>过滤把梯度集中在决策边界附近的题，类似主动学习。策略被推着去啃「刚刚会一点」的题，通过率曲线更陡。副作用：过易与过难题在更新里消失，评测若含这两端，会表现为「训练指标很好、评测两端差」。应保留一份不过滤的评测集。</p><p><span class="marginnote">约束写进目标，复现时关掉动态采样就不是 DAPO。社区 fork 常关它，分数不要写成官方 50。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>偏好 RM、连续分数很少出现精确全同，动态采样几乎不触发，本课主要服务 <a href="/llm/verifiable-reward">可验证奖励</a>。代码沙箱贵时，丢弃组的成本更高，要先用便宜的静态过滤（太易太难题移出题库）再动态采。下一课无 KL：动态采样提供的边界题，正是策略需要离开 SFT 的地方。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>全 0 / 全 1 组无相对梯度；动态采样过采样直到组内有分叉。</li><li>它按当前通过率过滤，不同于预设难度课程。</li><li>题库过难会采不满 batch；必须有超时回退。</li><li>主场是可验证 0/1；高噪声 RM 上慎用。</li><li>出处：Yu 等 DAPO Dynamic Sampling。</li></ul>',8))])}const D=i(h,[["render",c]]);export{P as __pageData,D as default};
